    //判断是否为虚拟网格经纬度边界区域范围
    public static boolean isPtInPoly_XN(Double lons, Double lats) {
        Point n1 = new Point(lons, lats);
        return isPtInPoly(n1.getX(), n1.getY(), jsonstrts);
    }

    //判断点位是否在多个区域内
    public static boolean isPtInPoly(double ALon, double ALat, List<String> locationInfos) {
        for (String locationInfo : locationInfos) {
            if (isPtInPoly(ALon, ALat, locationInfo)) {
                return true;
            }
        }
        return false;
    }

    //判断经纬度是否在区域内
    public static boolean isPtInPoly(double ALon, double ALat, String locationInfo) {

        JSONArray jsonObject = JSONArray.parseArray(locationInfo);
        Point[] ps = new Point[jsonObject.size() / 2];//114.323282,30.592786
        int j = 0;
        for (int i = 0; i < jsonObject.size(); i++) {
            BigDecimal lon = (BigDecimal) jsonObject.get(i);
            BigDecimal lat = (BigDecimal) jsonObject.get(++i);
            ps[j] = new Point(lon.doubleValue(), lat.doubleValue());
            j++;
        }

        int iSum, iCount, iIndex;
        double dLon1 = 0, dLon2 = 0, dLat1 = 0, dLat2 = 0, dLon;
        if (ps.length < 3) {
            return false;
        }
        iSum = 0;
        iCount = ps.length;
        for (iIndex = 0; iIndex < iCount; iIndex++) {
            if (iIndex == iCount - 1) {
                dLon1 = ps[iIndex].getX();
                dLat1 = ps[iIndex].getY();
                dLon2 = ps[0].getX();
                dLat2 = ps[0].getY();
            } else {
                dLon1 = ps[iIndex].getX();
                dLat1 = ps[iIndex].getY();
                dLon2 = ps[iIndex + 1].getX();
                dLat2 = ps[iIndex + 1].getY();
            }
            // 以下语句判断A点是否在边的两端点的水平平行线之间，在则可能有交点，开始判断交点是否在左射线上
            if (((ALat >= dLat1) && (ALat < dLat2)) || ((ALat >= dLat2) && (ALat < dLat1))) {
                if (Math.abs(dLat1 - dLat2) > 0) {
                    //得到 A点向左射线与边的交点的x坐标：
                    dLon = dLon1 - ((dLon1 - dLon2) * (dLat1 - ALat)) / (dLat1 - dLat2);
                    // 如果交点在A点左侧（说明是做射线与 边的交点），则射线与边的全部交点数加一：
                    if (dLon < ALon) {
                        iSum++;
                    }
                }
            }
        }
        if ((iSum % 2) != 0) {
            return true;
        }
        return false;
    }

    //随机生成点位方法
    public static Map<String, String> randomlonlat(String lon, String lat) {
        Map<String, String> maps = new HashMap<String, String>();
        String[] lonsz = lon.toString().split("\\.");
        String[] latsz = lat.toString().split("\\.");

        //随机生成后5位或*位
        String lons = lonsz[0] + "." + lonsz[1].substring(0, 1) + (new Random().nextInt(50000) + 10000);
        String lats = latsz[0] + "." + latsz[1].substring(0, 1) + (new Random().nextInt(50000) + 10000);
        maps.put("lon", lons);
        maps.put("lat", lats);
        return maps;
    }

    //某一区域内随机生成点位信息
    public static Map<String, String> randomlonlat(String locationInfo) {

        Map<String, String> maps = new HashMap<String, String>();

        //获取此区域内的中间点的经纬度 (就是求经纬度的一个平均值，组成一个大概的中间经纬度)
        JSONArray jsonObject = JSONArray.parseArray(locationInfo);
        BigDecimal lon = new BigDecimal(0);
        BigDecimal lat = new BigDecimal(0);
        BigDecimal minLon = new BigDecimal(0);
        BigDecimal maxLon = new BigDecimal(0);
        BigDecimal minLat = new BigDecimal(0);
        BigDecimal maxLat = new BigDecimal(0);

        for (int i = 0; i < jsonObject.size(); i++) {
            lon = (BigDecimal) jsonObject.get(i);
            lat = (BigDecimal) jsonObject.get(++i);

            if (minLon.compareTo(BigDecimal.valueOf(0)) == 0) {
                minLon = lon;
            }

            if (minLat.compareTo(BigDecimal.valueOf(0)) == 0) {
                minLat = lat;
            }

            if (minLon.compareTo(lon) == 1) {
                minLon = lon;
            }
            if (maxLon.compareTo(lon) == -1) {
                maxLon = lon;
            }
            if (minLat.compareTo(lat) == 1) {
                minLat = lat;
            }
            if (maxLat.compareTo(lat) == -1) {
                maxLat = lat;
            }
        }

        Random random = new Random();
        BigDecimal db = new BigDecimal(Math.random() * (maxLon.doubleValue() - minLon.doubleValue()) + minLon.doubleValue());
        String lons = db.setScale(6, BigDecimal.ROUND_HALF_UP).toString();// 小数后6位
        db = new BigDecimal(Math.random() * (maxLat.doubleValue() - minLat.doubleValue()) + minLat.doubleValue());
        String lats = db.setScale(6, BigDecimal.ROUND_HALF_UP).toString();

        maps.put("lon", lons);
        maps.put("lat", lats);
        return maps;
    }

    //经纬度不够六位补未0的方案
    public static String numberAfterFillZero(String str, int length) {
        StringBuffer buffer = new StringBuffer(str);
        if (buffer.length() >= length) {
            return buffer.toString();
        } else {
            while (buffer.length() < length) {
                buffer.append("0");
            }
        }
        return buffer.toString();
    }

    //通过边界范围经纬度，在此范围内生成不重复的经纬度信息
    public static String genRandomLatAndLon(String locationInfo, HashMap<String, String> distMap) {

        //返回值
        String result = "";

        //去掉后两位进行点位重叠key生成
        String key = "";
        while (true) {
            if (locationInfo.startsWith("[[")) {
                //如果为多网格情况 就随机取一个网格
                JSONArray array = JSONArray.parseArray(locationInfo);
                locationInfo = array.get(new Random().nextInt(array.size())).toString();
            }
            Map<String, String> randomMap = randomlonlat(locationInfo);
            //判断生成的点位是否在范围内
            while (!isPtInPoly(Double.parseDouble(randomMap.get("lon")), Double.parseDouble(randomMap.get("lat")), locationInfo)) {
                //如果点位生成在区域外面，就重新生成
                randomMap = randomlonlat(locationInfo);
            }
            key = randomMap.get("lon").substring(0, 8) + randomMap.get("lat").substring(0, 8);
            if (distMap.get(key) == null) {
                //如果没有重复的话，就存入到map中
                result = randomMap.get("lon") + "," + randomMap.get("lat");
                distMap.put(key, key);
                break;
            }
        }
        return result;

    }

    /**
     * 判断经纬度是否在边界内 - 使用gpt4编写
     *
     * @param longitude      经度
     * @param latitude       纬度
     * @param boundaryString 边界信息 一维数组构成的边界
     * @return 是或否
     */
    public static boolean isPointInBoundary(double longitude, double latitude, String boundaryString) {
        List<Point2D.Double> points = parseBoundaryString(boundaryString);
        if (points.isEmpty()) {
            return false;
        }

        Path2D.Double polygon = new Path2D.Double();
        Point2D.Double firstPoint = points.get(0);
        polygon.moveTo(firstPoint.getX(), firstPoint.getY());
        for (int i = 1; i < points.size(); i++) {
            Point2D.Double point = points.get(i);
            polygon.lineTo(point.getX(), point.getY());
        }
        polygon.closePath();

        return polygon.contains(longitude, latitude);
    }

    private static List<Point2D.Double> parseBoundaryString(String boundaryString) {
        List<Point2D.Double> points = new ArrayList<>();
        if (boundaryString == null || boundaryString.isEmpty()) {
            return points;
        }

        String cleanString = boundaryString.replaceAll("[\\[\\]\\s]", "");
        String[] coordinates = cleanString.split(",");
        if (coordinates.length % 2 != 0) {
            return points;
        }

        for (int i = 0; i < coordinates.length; i += 2) {
            double longitude = Double.parseDouble(coordinates[i]);
            double latitude = Double.parseDouble(coordinates[i + 1]);
            points.add(new Point2D.Double(longitude, latitude));
        }

        return points;
    }

    public static String convertCoordinates(String input) {
        JSONArray jsonArray = JSONArray.parseArray(input);
        JSONArray innerArray = jsonArray.getJSONArray(0);
        StringBuilder output = new StringBuilder("[[[");

        for (int i = 0; i < innerArray.size(); i++) {
            JSONObject point = innerArray.getJSONObject(i);
            double x = point.getDouble("x");
            double y = point.getDouble("y");
            output.append("[").append(x).append(",").append(y).append("]");
            if (i < innerArray.size() - 1) {
                output.append(",");
            }
        }
        output.append("]]]");
        return output.toString();
    }


    // 地球半径，单位：千米
    private static final double EARTH_RADIUS = 6371.0;

    /**
     * 计算从给定经纬度开始，向指定方向偏移指定距离后的新经纬度。
     *
     * @param lon      给定经度
     * @param lat      给定纬度
     * @param bearing  方向，单位：度数 正北为0度，顺时针累加
     * @param distance 偏移距离，单位：千米
     * @return 新经纬度
     */
    public static double[] calculateOffset(double lon, double lat, double bearing, double distance) {
        double[] lonLat = new double[2];
        double lat1 = Math.toRadians(lat);
        double lon1 = Math.toRadians(lon);
        double bearingRad = Math.toRadians(bearing);
        double angularDistance = distance / EARTH_RADIUS;

        double lat2 = Math.asin(Math.sin(lat1) * Math.cos(angularDistance) +
                Math.cos(lat1) * Math.sin(angularDistance) * Math.cos(bearingRad));
        double lon2 = lon1 + Math.atan2(Math.sin(bearingRad) * Math.sin(angularDistance) * Math.cos(lat1),
                Math.cos(angularDistance) - Math.sin(lat1) * Math.sin(lat2));

        lonLat[0] = Math.toDegrees(lon2);
        lonLat[1] = Math.toDegrees(lat2);

        return lonLat;
    }


    /**
     * 计算两个经纬度之间的距离。
     *
     * @param lon1 第一个经度
     * @param lat1 第一个纬度
     * @param lon2 第二个经度
     * @param lat2 第二个纬度
     * @return 两点之间的距离，单位：千米
     */
    public static double calculateDistance(double lon1, double lat1, double lon2, double lat2) {
        double lat1Rad = Math.toRadians(lat1);
        double lon1Rad = Math.toRadians(lon1);
        double lat2Rad = Math.toRadians(lat2);
        double lon2Rad = Math.toRadians(lon2);

        double dLat = lat2Rad - lat1Rad;
        double dLon = lon2Rad - lon1Rad;

        double a = Math.pow(Math.sin(dLat / 2), 2) +
                Math.cos(lat1Rad) * Math.cos(lat2Rad) *
                        Math.pow(Math.sin(dLon / 2), 2);
        double c = 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));

        return EARTH_RADIUS * c;
    }


    /**
     * 计算经纬度是否在multipolygon格式的边界区域内
     *
     * @param longitude    经度
     * @param latitude     纬度
     * @param multiPolygon multipolygon边界
     * @return 是或否
     */
    public static boolean isPointInMultiPolygon(double longitude, double latitude,
                                                double[][][][] multiPolygon) {
        if (multiPolygon == null) {
            return false;
        }
        for (double[][][] polygon : multiPolygon) {
            if (isPointInPolygon(latitude, longitude, polygon[0])) {
                boolean isInHole = false;
                for (int i = 1; i < polygon.length; i++) {
                    if (isPointInPolygon(latitude, longitude, polygon[i])) {
                        isInHole = true;
                        break;
                    }
                }
                if (!isInHole) {
                    return true;
                }
            }
        }
        return false;
    }

    private static boolean isPointInPolygon(double latitude, double longitude, double[][] polygon) {
        Path2D path = new Path2D.Double();
        path.moveTo(polygon[0][0], polygon[0][1]);
        for (int i = 1; i < polygon.length; i++) {
            path.lineTo(polygon[i][0], polygon[i][1]);
        }
        path.closePath();

        return path.contains(longitude, latitude);
    }


    public static double[] generateRandomLngLatInMultiPolygon(double[][][][] multiPolygon) {
        if (multiPolygon == null || multiPolygon.length == 0) {
            throw new IllegalArgumentException("Invalid MultiPolygon data");
        }

        Random random = new Random();
        double[] result = new double[2];

        while (true) {
            // 选择一个随机的多边形
            int polygonIndex = random.nextInt(multiPolygon.length);
            double[][][] polygon = multiPolygon[polygonIndex];

            // 计算多边形的边界
            double minLng = polygon[0][0][0], maxLng = polygon[0][0][0];
            double minLat = polygon[0][0][1], maxLat = polygon[0][0][1];

            for (double[][] ring : polygon) {
                for (double[] coord : ring) {
                    minLng = Math.min(minLng, coord[0]);
                    maxLng = Math.max(maxLng, coord[0]);
                    minLat = Math.min(minLat, coord[1]);
                    maxLat = Math.max(maxLat, coord[1]);
                }
            }

            // 生成一个随机经纬度
            double lng = minLng + random.nextDouble() * (maxLng - minLng);
            double lat = minLat + random.nextDouble() * (maxLat - minLat);

            // 判断随机生成的点是否在多边形内
            if (pointInMultiPolygon(lng, lat, polygon)) {
                result[0] = lng;
                result[1] = lat;
                break;
            }
        }
        return result;
    }

    // 判断点是否在多边形内的方法
    private static boolean pointInMultiPolygon(double lng, double lat, double[][][] polygon) {
        boolean result = false;
        for (double[][] ring : polygon) {
            if (pointInRing(lng, lat, ring)) {
                result = !result;
            }
        }
        return result;
    }

    // 判断点是否在环内的方法
    private static boolean pointInRing(double lng, double lat, double[][] ring) {
        boolean inside = false;
        for (int i = 0, j = ring.length - 1; i < ring.length; j = i++) {
            if ((ring[i][1] > lat) != (ring[j][1] > lat) &&
                    (lng < (ring[j][0] - ring[i][0]) * (lat - ring[i][1]) / (ring[j][1] - ring[i][1]) + ring[i][0])) {
                inside = !inside;
            }
        }
        return inside;
    }



