    public static double[][][][] boundsToMultipolygon(double[][] bounds) {
        int length = bounds.length;
        double[][][] polygon = new double[length + 1][][];
        for (int i = 0; i < length; i++) {
            polygon[i] = new double[][] { bounds[i] };
        }
        polygon[length] = new double[][] { bounds[0] };  // make it a closed loop
        return new double[][][][] { polygon };  // make it four-dimensional
    }

